CREATE TABLE plans (id VARCHAR(191) PRIMARY KEY, code VARCHAR(128) NOT NULL, name TEXT NOT NULL, description TEXT NOT NULL, currency VARCHAR(3) NOT NULL, billing_interval VARCHAR(16) NOT NULL, base_amount_minor BIGINT NOT NULL, trial_days INT NOT NULL DEFAULT 0, status VARCHAR(32) NOT NULL, entitlements_json JSON NOT NULL, version BIGINT NOT NULL DEFAULT 1, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, created_by TEXT NOT NULL, updated_by TEXT NOT NULL, UNIQUE KEY uk_plans_code(code), KEY idx_plans_status_code(status,code));
CREATE TABLE usage_prices (id VARCHAR(191) PRIMARY KEY, plan_id VARCHAR(191) NOT NULL, meter_code VARCHAR(191) NOT NULL, included_quantity BIGINT NOT NULL DEFAULT 0, unit_quantity BIGINT NOT NULL, unit_amount_minor BIGINT NOT NULL, pricing_model VARCHAR(32) NOT NULL, tiers_json JSON NOT NULL, version BIGINT NOT NULL DEFAULT 1, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, created_by TEXT NOT NULL, updated_by TEXT NOT NULL, UNIQUE KEY uk_usage_prices_plan_meter(plan_id,meter_code));
CREATE TABLE subscriptions (id VARCHAR(191) PRIMARY KEY, tenant_id VARCHAR(191) NOT NULL, plan_id VARCHAR(191) NOT NULL, status VARCHAR(32) NOT NULL, current_period_start DATETIME(6) NOT NULL, current_period_end DATETIME(6) NOT NULL, cancel_at_period_end BOOLEAN NOT NULL DEFAULT FALSE, canceled_at DATETIME(6) NULL, external_reference TEXT NOT NULL, pending_plan_id VARCHAR(191) NULL, pending_change_at DATETIME(6) NULL, version BIGINT NOT NULL DEFAULT 1, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, created_by TEXT NOT NULL, updated_by TEXT NOT NULL, KEY idx_subscriptions_tenant_status(tenant_id,status,updated_at));
CREATE TABLE subscription_claims (tenant_id VARCHAR(191) PRIMARY KEY, subscription_id VARCHAR(191) NOT NULL, version BIGINT NOT NULL DEFAULT 1, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, created_by TEXT NOT NULL, updated_by TEXT NOT NULL);
CREATE TABLE invoices (id VARCHAR(191) PRIMARY KEY, number VARCHAR(191) NOT NULL UNIQUE, tenant_id VARCHAR(191) NOT NULL, subscription_id VARCHAR(191) NOT NULL, currency VARCHAR(3) NOT NULL, status VARCHAR(32) NOT NULL, period_start DATETIME(6) NOT NULL, period_end DATETIME(6) NOT NULL, subtotal_minor BIGINT NOT NULL, discount_minor BIGINT NOT NULL DEFAULT 0, tax_minor BIGINT NOT NULL DEFAULT 0, total_minor BIGINT NOT NULL, paid_minor BIGINT NOT NULL DEFAULT 0, refunded_minor BIGINT NOT NULL DEFAULT 0, due_at DATETIME(6) NULL, finalized_at DATETIME(6) NULL, paid_at DATETIME(6) NULL, version BIGINT NOT NULL DEFAULT 1, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, created_by TEXT NOT NULL, updated_by TEXT NOT NULL, KEY idx_invoices_tenant_status_created(tenant_id,status,created_at));
CREATE TABLE invoice_lines (id VARCHAR(191) PRIMARY KEY, invoice_id VARCHAR(191) NOT NULL, type VARCHAR(32) NOT NULL, description TEXT NOT NULL, meter_code VARCHAR(191) NOT NULL, quantity BIGINT NOT NULL, unit_quantity BIGINT NOT NULL, unit_amount_minor BIGINT NOT NULL, amount_minor BIGINT NOT NULL, metadata_json JSON NOT NULL, version BIGINT NOT NULL DEFAULT 1, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, created_by TEXT NOT NULL, updated_by TEXT NOT NULL, KEY idx_invoice_lines_invoice(invoice_id,id));
CREATE TABLE invoice_generation_keys (idempotency_key VARCHAR(191) PRIMARY KEY, invoice_id VARCHAR(191) NOT NULL, tenant_id VARCHAR(191) NOT NULL, request_hash VARCHAR(64) NOT NULL, version BIGINT NOT NULL DEFAULT 1, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, created_by TEXT NOT NULL, updated_by TEXT NOT NULL);
CREATE TABLE payment_attempts (id VARCHAR(191) PRIMARY KEY, invoice_id VARCHAR(191) NOT NULL, tenant_id VARCHAR(191) NOT NULL, provider VARCHAR(64) NOT NULL, provider_payment_id VARCHAR(191) NOT NULL, idempotency_key VARCHAR(191) NOT NULL UNIQUE, request_hash VARCHAR(64) NOT NULL, currency VARCHAR(3) NOT NULL, amount_minor BIGINT NOT NULL, status VARCHAR(32) NOT NULL, failure_code TEXT NOT NULL, failure_message TEXT NOT NULL, processed_at DATETIME(6) NULL, version BIGINT NOT NULL DEFAULT 1, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, created_by TEXT NOT NULL, updated_by TEXT NOT NULL, KEY idx_payment_attempts_invoice_created(invoice_id,created_at));
CREATE TABLE payment_provider_events (provider VARCHAR(64) NOT NULL, event_id VARCHAR(191) NOT NULL, payment_attempt_id VARCHAR(191) NOT NULL, version BIGINT NOT NULL DEFAULT 1, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, created_by TEXT NOT NULL, updated_by TEXT NOT NULL, PRIMARY KEY(provider,event_id));
CREATE TABLE refunds (id VARCHAR(191) PRIMARY KEY, payment_attempt_id VARCHAR(191) NOT NULL, invoice_id VARCHAR(191) NOT NULL, provider_refund_id VARCHAR(191) NOT NULL, idempotency_key VARCHAR(191) NOT NULL UNIQUE, request_hash VARCHAR(64) NOT NULL, amount_minor BIGINT NOT NULL, reason TEXT NOT NULL, status VARCHAR(32) NOT NULL, version BIGINT NOT NULL DEFAULT 1, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, created_by TEXT NOT NULL, updated_by TEXT NOT NULL);
CREATE TABLE billing_outbox_events (id VARCHAR(191) PRIMARY KEY, subject VARCHAR(255) NOT NULL, envelope LONGBLOB NOT NULL, attempts INT NOT NULL DEFAULT 0, available_at DATETIME(6) NOT NULL, published_at DATETIME(6) NULL, last_error TEXT NOT NULL, version BIGINT NOT NULL DEFAULT 1, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, created_by TEXT NOT NULL, updated_by TEXT NOT NULL, KEY idx_billing_outbox_pending(published_at,available_at));
